const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={vault:'M4 5h16v15H4z M4 9h16 M8 5V3 M16 5V3 M8 13h3v3H8z',vision:'M3 7h4l2-3h6l2 3h4v13H3z M16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0',scout:'M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14 M15 15l6 6',market:'M3 9l2-6h14l2 6 M4 10v11h16V10 M9 21v-7h6v7 M3 9h18',flow:'M4 5h10 M11 2l3 3-3 3 M20 19H10 M13 16l-3 3 3 3 M4 11v8h3 M20 13V5h-3',pulse:'M2 12h5l3-8 4 16 3-8h5',foundation:'M12 2L2 7l10 5 10-5-10-5 M2 12l10 5 10-5 M2 17l10 5 10-5',plus:'M12 5v14 M5 12h14',arrow:'M9 5l7 7-7 7',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',upload:'M12 16V4 M7 9l5-5 5 5 M4 16v5h16v-5',shield:'M12 2l8 4v6c0 5-8 10-8 10S4 17 4 12V6l8-4 M8 12l3 3 5-6',card:'M5 3h14v18H5z M8 6h8 M8 16h8 M8 18h5 M9 9h6v4H9z',comic:'M4 3h14l2 3v15H4z M8 6h7 M8 10h8 M8 14h8 M8 18h5',box:'M3 7l9-5 9 5v11l-9 4-9-4V7 M3 7l9 5 9-5 M12 12v10 M7 4l10 5',coin:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M15 8h-4a2 2 0 0 0 0 4h2a2 2 0 0 1 0 4H9 M12 6v12',check:'M5 12l4 4L19 6',pin:'M19 9c0 5-7 13-7 13S5 14 5 9a7 7 0 1 1 14 0 M15 9a3 3 0 1 1-6 0 3 3 0 0 1 6 0',edit:'M15 4l5 5 M4 15l12-12 5 5-12 12H4v-5',link:'M10 14l4-4 M8 16l-2 2a4 4 0 0 1-6-6l4-4 M16 8l2-2a4 4 0 0 1 6 6l-4 4',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 7v5l3 2'};
const icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]??icons.card}"/></svg>`;
const labels={card:'Trading card',comic:'Comic book',bulk:'Bulk lot',other:'Other collectible',intake:'Intake',ready:'Ready',listed:'Listed',hold:'Hold',sold:'Sold',review:'Needs review',verified:'Verified',unverified:'Unverified',awaiting:'Awaiting receipt'};
const badge=(key)=>`<span class="badge ${esc(key)}">${labels[key]??esc(key)}</span>`;
const localDate=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const key=mode=>`btco-os:v1:${mode}`;
let mode='demo',state,view='vault',type='all',filter='all',verification='all',coverage='all',search='',page=1,pendingImport=null,pendingRefresh=null,refreshBusy=false,toastTimer;
const PAGE_SIZE=20;
(async function boot(){
  try {
    mode=localStorage.getItem('btco-os:mode')==='demo'?'demo':'work';
    let work=await readLocalWorkspace('work');
    try{work=await connectShared(work);}catch(e){work=await offlineWorkspace(work);toast('Shared inventory unavailable: '+e.message);}
    state=mode==='work'?work:await readWorkspace('demo');render();
  }catch(e){blocked(e);}
})();

function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function download(name,content,mime='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type:mime}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function blocked(error){$('#app').innerHTML=`<main><div class="panel architecture"><h1>Saved data needs attention</h1><p>${esc(error.message)}</p><p>No records have been replaced. Download the saved data before making repairs.</p><button class="btn" id="raw-backup">Download raw saved data</button></div></main>`;$('#raw-backup').onclick=async()=>{try{download(`BTCo-OS-${mode}-recovery.json`,await rawWorkspaceBackup(mode));}catch(e){toast(e.message);}};}
async function persist(next){state=await writeWorkspace(mode,state,next);render();}
function openModal(title,subtitle,body){const m=$('#modal');m.innerHTML=`<div class="modal-head"><div><h2 id="modal-title">${esc(title)}</h2><p>${esc(subtitle)}</p></div><button class="close-btn" aria-label="Close dialog" data-action="close">×</button></div><div class="modal-body">${body}</div>`;if(!m.open)m.showModal();}
function closeModal(){$('#modal').close();pendingImport=null;pendingRefresh=null;}
function modalError(e){const target=$('#form-error');if(target){target.textContent=e.message;target.scrollIntoView({block:'nearest'});}else toast(e.message);}
async function changeMode(){try{const nextMode=mode==='demo'?'work':'demo',next=await readWorkspace(nextMode);localStorage.setItem('btco-os:mode',nextMode);mode=nextMode;state=next;filter=verification=coverage='all';type='all';search='';page=1;view='vault';render();toast(mode==='work'?'Working inventory opened. Demo data stays separate.':'Demo workspace opened. All examples are fictional.');}catch(e){toast(e.message);}}

function render(){
  unmountVision();
  const s=summary(state),title=view[0].toUpperCase()+view.slice(1);
  $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="wordmark">BTCo<span>OS</span></div><div class="brandbars"><i></i><i></i><i></i></div></div><div class="navlabel">Your workspace</div><nav class="nav" aria-label="Modules">${['vault','vision','scout','market','flow','pulse'].map(n=>`<button data-nav="${n}" class="${view===n?'active':''}" ${view===n?'aria-current="page"':''}>${icon(n)}${n[0].toUpperCase()+n.slice(1)}<em>${n==='vault'?'01':n==='vision'?'REVIEW':n==='pulse'?'BASIC':n==='scout'?'EVALUATE':'REVIEW'}</em></button>`).join('')}<div class="navlabel">System</div><button data-nav="foundation" class="${view==='foundation'?'active':''}">${icon('foundation')}Foundation</button></nav><div class="sidebar-foot"><div class="workspace"><div class="avatar">BT</div><div><strong>Ballard Trading Co.</strong><small>Independent by design.</small></div></div><div class="version"><i class="dot"></i> Phase 1 · v0.11.1</div></div></aside><div class="main-wrap"><header class="topbar"><div class="crumb">Ballard Trading Co.<span>/</span><strong>${title}</strong></div><div class="topright"><span class="date">${new Date().toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}</span><span class="local-pill">${icon('shield',13)}${mode==='demo'?'Local demo':syncStatus.phase==='connected'?'Shared inventory':'Offline · read only'}</span></div></header><main id="main"><div class="page-heading"><div><div class="eyebrow">${view==='vault'?'A place for every piece':view==='pulse'?'Know your numbers':view==='vision'?'From camera to collection':'Built for the way we work'}</div><h1>${view==='vault'?'The Vault':view==='pulse'?'Business pulse':view==='vision'?'BTCo Vision':['scout','market','flow'].includes(view)?title:'The OS, piece by piece.'}</h1><p>${view==='vault'?'From the receiving tray to the next collector.':view==='pulse'?'Actual records. Visible costs. Clear next steps.':view==='vision'?'Review the identity. Find the inventory. Know the buying costs.':'One shared inventory. Six connected modules.'}</p></div><div class="actions"><button class="btn" data-action="backup">${icon('download',15)}Back up & import</button>${view==='vault'?`<button class="btn primary" data-action="add">${icon('plus',15)}Add inventory</button>`:''}</div></div><div class="mode-banner ${mode==='work'?'work':''}"><div><strong>${mode==='demo'?'DEMO WORKSPACE':'WORKING INVENTORY'}</strong> ${mode==='demo'?'Fictional examples only. Your actual inventory is separate.':'Use the same ChatGPT account on Mac and iPhone. Saved changes are shared; original device records are preserved.'}</div><button class="text-btn" data-action="switch-mode">${mode==='demo'?'Open my inventory →':'Explore demo →'}</button></div>${syncPanel()}${sourceNotice()}${view==='vision'?visionMarkup():view==='foundation'?foundation():['scout','market','flow'].includes(view)?moduleMarkup(view,state):stats(s)+(view==='pulse'?pulse():vault(s))}<footer class="page-foot"><span>BTCo OS / Ballard Trading Co.</span><span>USD · Shared Vault · No marketplace writes</span></footer></main></div></div>`;
  if(view==='vision'){
    const visionMode=mode;
    const saveVision=async next=>{if(mode!==visionMode)throw Error('Workspace changed. Reopen Vision before saving.');const saved=await writeWorkspace(visionMode,state,next);if(mode===visionMode)state=saved;};
    mountVision($('#vision-root'),{getState:()=>state,onOpen:detail,onDraftSave:saveVision,onSave:async(next,item)=>{await saveVision(next);if(mode!==visionMode)return;view='vault';render();detail(item.id);toast('CDP SKU linked. Listing management stays in CDP.');}});
  }
  if(['scout','market','flow'].includes(view))mountModule(view,state,$('#main'));
  if(view==='vault'){renderResults();$('#search').addEventListener('input',e=>{search=e.target.value;page=1;renderResults();});$('#status-filter').addEventListener('change',e=>{filter=e.target.value;page=1;renderResults();});$('#verify-filter').addEventListener('change',e=>{verification=e.target.value;page=1;renderResults();});}
}
function stats(s){return `<section class="stats" aria-label="Inventory summary">${[
 ['Open inventory',s.units.toLocaleString(),`${s.skus} open SKUs · ${s.review} excluded for review`,'box'],
 ['Known inventory cost',s.skus&&s.unknownCosts===s.skus?'—':money(s.cost),`${s.unknownCosts?`${s.unknownCosts} SKU${s.unknownCosts===1?'':'s'} with unknown cost`:'Known remaining acquisition cost'}`,'coin'],
 ['Listed in records',s.listed.toLocaleString(),`${s.ready} ready to list · manual records`,'market'],
 ['Recorded net profit',!s.sales&&s.externalSales?'—':money(s.net),`${s.sales} recorded sales · ${s.externalSales} source sale lines unreconciled`,'pulse']].map(([label,value,note,i],n)=>`<article class="stat"><div class="stat-title">${label}${icon(i,17)}</div><div class="stat-number ${n===3?(s.net>=0?'positive':'negative'):''}">${value}</div><div class="stat-note">${note}</div></article>`).join('')}</section>`;}
function vault(s){return `${channelOverview()}<div class="vault-layout"><section class="panel"><div class="panel-head"><h2>Inventory <span class="count">${state.items.length}</span></h2><button class="text-btn" data-action="export-csv">Export CSV</button></div><div class="subtabs" role="group" aria-label="Item types">${[['all','All items'],['card','Cards'],['comic','Comics'],['graded','Graded'],['bulk','Bulk lots']].map(([k,label])=>`<button data-type="${k}" class="${type===k?'selected':''}" aria-pressed="${type===k}">${label}</button>`).join('')}</div><div class="filters"><div class="search">${icon('scout',15)}<input id="search" type="search" value="${esc(search)}" placeholder="Search title, player, SKU, location…" aria-label="Search inventory"></div><select id="status-filter" aria-label="Filter by status">${options(['all',...STATUSES,'sold','review','unknown-cost'],filter,{all:'All statuses','unknown-cost':'Unknown cost'})}</select><select id="verify-filter" aria-label="Filter physical verification">${options(['all',...VERIFY],verification,{all:'All verification'})}</select></div>${coverage!=='all'?'<div class="filter-notice"><span>eBay only · available records without a CDP match</span><button class="text-btn" data-action="clear-filters">Show all inventory</button></div>':''}<div id="inventory-results"></div></section><aside class="rail"><div class="rail-panel"><h3>${icon('flow',16)}Next up</h3><button class="queue-row" data-nav="vision"><span>CDP intake drafts</span><b>${intakeRecords(state).filter(r=>r.status==='draft').length}</b></button><button class="queue-row" data-queue="review"><span>Reconcile source records</span><b>${s.review}</b></button><button class="queue-row" data-queue="unverified"><span>Verify physical inventory</span><b>${s.unverified}</b></button><button class="queue-row" data-queue="unknown-cost"><span>Add missing costs</span><b>${s.unknownCosts}</b></button><button class="queue-row" data-queue="ready"><span>Ready to list</span><b>${s.ready}</b></button></div><div class="health"><div class="eyebrow">The foundation</div><h3>Know what you own.</h3><p>Every SKU connects the item, its home, its cost, and what happens next.</p><button class="btn small" data-action="add">${icon('plus',13)}Receive an item</button></div><div class="rail-panel"><h3>${icon('shield',16)}Keep a copy</h3><p>Shared saves keep the latest 10 recovery snapshots. Your original browser records remain preserved.</p><button class="btn small" data-action="cloud-backups">${icon('download',13)}Recovery snapshots</button></div><p class="rail-note">Listed is a manual status. It does not verify or change a live marketplace listing.</p></aside></div>`;}
function channelOverview(){
  const only=state.items.filter(i=>isEbayOnlyOpen(state,i)).length;
  const known=channel=>state.items.filter(i=>listingPrice(i,channel).priceCents!==null).length;
  return `<section class="channel-overview" aria-label="Marketplace coverage"><button class="channel-summary" data-coverage="ebay-only" aria-pressed="${coverage==='ebay-only'}"><div class="eyebrow">eBay only <span>· no CDP match</span></div><div class="channel-count">${only.toLocaleString()} <span>available records</span></div><p>In the eBay snapshot, without a matched CDP record in the saved data. CollX coverage may be unknown.</p><span class="channel-link">View these records ${icon('arrow',13)}</span></button><div class="channel-summary price-coverage"><div class="eyebrow">Listing prices captured</div><div class="price-totals"><span><b>${known('ebay').toLocaleString()}</b>eBay records</span><span><b>${known('collx').toLocaleString()}</b>CollX records</span></div><p>Saved asking prices appear on every inventory row. CollX prices are not included in the CDP export; record them in Edit item. Source dates appear inside each record.</p></div></section>`;
}
function priceRows(item){
  return `<div class="channel-prices">${[['ebay','eBay'],['collx','CollX']].map(([key,label])=>{
    const p=listingPrice(item,key);
    return `<div title="${esc([p.source,p.asOf].filter(Boolean).join(' · ')||'No channel-specific price recorded')}"><span>${label}</span><b class="${p.priceCents===null?'price-missing':''}">${p.priceCents===null?'Not captured':money(p.priceCents)}</b></div>`;
  }).join('')}</div>`;
}
function channelDetails(item){
  const src=item.source;
  return `<section class="source-detail"><h3>Listing prices · USD per sellable unit</h3><dl class="details">${[['ebay','eBay'],['collx','CollX']].map(([key,label])=>{
    const p=listingPrice(item,key);
    return `<div><dt>${label} listing price</dt><dd><strong>${p.priceCents===null?'Not captured':money(p.priceCents)}</strong><br><span class="field-help">${esc([p.source,p.asOf].filter(Boolean).join(' · ')||'No channel-specific price in the saved sources.')}</span></dd></div>`;
  }).join('')}${src?.cdpCollxStatus!==undefined?`<div><dt>CollX status in CDP · ${esc(src.cdpChannelAsOf)}</dt><dd>${esc(src.cdpCollxStatus||'Not recorded')} · ${esc(src.cdpCollxQuantity)} reported available<br><span class="field-help">Historical status; does not confirm a current listing or its price.</span></dd></div><div><dt>CDP start price · channel unspecified</dt><dd>${esc(src.cdpStartPriceReported||'Not recorded')}<br><span class="field-help">Source reference only. Not used as the CollX listing price.</span></dd></div>`:''}</dl><p class="field-help">Use Edit item to capture each marketplace's actual asking price. These are dated records, not live marketplace checks.</p></section>`;
}
function filteredItems(){const q=search.trim().toLowerCase();return state.items.filter(i=>(coverage==='all'||isEbayOnlyOpen(state,i))&&(type==='all'||(type==='graded'?!!i.gradeCompany:i.kind===type))&&(filter==='all'||(filter==='unknown-cost'?i.costCents===null&&remaining(state,i)>0:status(state,i)===filter))&&(verification==='all'||(verification==='unverified'?i.verification!=='verified':i.verification===verification))&&(!q||[i.title,i.sku,i.subject,i.year,i.setName,i.number,i.serial,i.cert,i.location,i.acquisitionRef,i.vendor].some(x=>x.toLowerCase().includes(q))));}
function renderResults(){const items=filteredItems(),start=(page-1)*PAGE_SIZE,current=items.slice(start,start+PAGE_SIZE);
  $('#inventory-results').innerHTML=!items.length?`<div class="empty">${icon('vault',38)}<h3>${state.items.length?'No matching inventory.':'Your inventory starts here.'}</h3><p>${state.items.length?'Try another search or clear your filters.':'Add a physical item, give it a location, and record its cost. Existing spreadsheets and marketplace inventory remain untouched.'}</p><button class="btn primary" data-action="${state.items.length?'clear-filters':'add'}">${state.items.length?'Clear filters':'+ Add your first item'}</button></div>`:`<div class="table-wrap"><table class="inventory"><thead><tr><th>Item / identification</th><th class="location-col">Location</th><th>Listing prices / unit</th><th>Cost left</th><th>Status</th><th aria-label="Open"></th></tr></thead><tbody>${current.map(i=>`<tr class="item-row" data-item="${esc(i.id)}"><td class="item-info"><div class="item-cell"><div class="item-art ${i.gradeCompany?'graded':i.kind}">${/^https:\/\/i\.ebayimg\.com\//.test(i.source?.frontImage??'')?`<img src="${esc(i.source.frontImage)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:icon(i.gradeCompany?'shield':i.kind==='comic'?'comic':i.kind==='bulk'?'box':'card',19)}</div><div><button class="item-title" data-action="detail" data-id="${esc(i.id)}">${esc(i.title)}</button><div class="item-meta"><span class="mono">${esc(i.sku)}</span>${i.autograph?'<span class="mini-tag auto">Auto</span>':''}${i.serial?`<span class="mini-tag">${esc(i.serial)}</span>`:''}${i.gradeCompany?`<span class="mini-tag">${esc(i.gradeCompany)} ${esc(i.grade)}</span>`:''}${i.source?.autographClaimed&&!i.autograph?'<span class="mini-tag auto" title="Autograph described in source; unverified">Auto?</span>':''}<span>${i.availability==='review'?'Unreconciled':`${remaining(state,i)}/${i.quantity} units`}</span>${i.source?`<span class="source-date">${esc(i.source.asOf)}</span>`:''}</div></div></div></td><td class="location-col"><div class="location">${esc(i.location)||'Unassigned'}</div></td><td class="listing-price-col">${priceRows(i)}</td><td class="cost-col amount ${i.costCents==null?'muted':''}">${money(remainingCost(state,i))}</td><td class="status-col">${badge(status(state,i))}</td><td class="row-arrow">${icon('arrow',13)}</td></tr>`).join('')}</tbody></table></div><div class="table-foot"><span>${start+1}–${Math.min(start+PAGE_SIZE,items.length)} of ${items.length} SKUs</span><div class="actions">${items.length>PAGE_SIZE?`<button class="btn small" data-action="previous" ${page===1?'disabled':''}>Previous</button><button class="btn small" data-action="next" ${start+PAGE_SIZE>=items.length?'disabled':''}>Next</button>`:''}<span>Click an item to open</span></div></div>`;
}
function options(values,selected,custom={}){return values.map(v=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(custom[v]??labels[v]??v)}</option>`).join('');}
function sourceNotice(){
  if(mode==='demo'||!state.importBatches?.length)return '';
  if(state.ebayRefresh?.source==='ebay-active-api'){const r=state.ebayRefresh,stale=Date.now()-Date.parse(r.observedAt)>36*3600000;return `<section class="source-notice"><div><strong>eBay API · ${r.stats.sourceRows.toLocaleString()} active listings${stale?' · update overdue':''}</strong><p>Checked ${esc(new Date(r.observedAt).toLocaleString())}. CDP master SKUs and recorded stock preserved. ${r.stats.added} new review records · ${r.stats.missing} listings not observed. CDP and CollX details retain their own source dates.</p></div><button class="btn small" data-action="source-summary">Update details</button></section>`;}
  if(state.ebayRefresh)return `<section class="source-notice"><div><strong>eBay report · ${esc(state.ebayRefresh.asOf)}</strong><p>CDP details remain historical (September 26). Quantity conflicts and missing listings are held for review. Source reports are not a live stock check.</p></div><button class="btn small" data-action="source-summary">Import details</button></section>`;
  const original=state.importBatches.find(b=>b.id==='btco-inventory-20261011'),dates=[...new Set(state.importBatches.map(b=>b.listingAsOf))];
  return `<section class="source-notice"><div><strong>${icon('link',15)} Imported inventory · dated source records</strong><p>${original?'Base eBay snapshot: October 6. CDP enrichment: September 26. Orders checked through October 11.':`Report dates: ${dates.map(esc).join(', ')}.`} Newly listed and ended items still need a current eBay refresh. Historical review records are excluded from available stock.</p></div><button class="btn small" data-action="source-summary">Import details</button></section>`;
}
function sourceDetails(item){
  const src=item.source;if(!src)return '';
  if(src.system==='vision-review'){
    const scan=src.visionScan;
    return `<section class="source-detail"><h3>Vision identification evidence</h3><dl class="details"><div><dt>Reviewed</dt><dd>${esc(src.asOf)}</dd></div><div><dt>Identification source</dt><dd>${scan?esc(scan.provider)+' · '+esc(scan.identifiedAt):'Manually entered or pasted identification'}</dd></div>${scan?`<div><dt>Scan reference</dt><dd>${esc(scan.scanId)}</dd></div><div><dt>Recognition model</dt><dd>${esc(scan.model)}</dd></div>`:''}${scan?.psa?`<div><dt>PSA record lookup</dt><dd>${esc(scan.psa.certNumber)} · ${scan.psa.recordFound?'Record found':'Not confirmed'} · ${esc(scan.psa.fetchedAt)}</dd></div>`:''}</dl><p class="field-help">Reviewed identity is separate from physical verification and authenticity. Original photos are not stored.</p><details><summary>Original identification</summary><pre class="vision-json-result">${esc(JSON.stringify(scan?.originalCard??src.card,null,2))}</pre></details></section>`;
  }
  const sales=(state.externalSales??[]).filter(s=>s.itemId===item.id);
  return `<section class="source-detail"><h3>Source & reconciliation</h3><dl class="details"><div><dt>Source record</dt><dd>${esc(src.system)} · ${esc(src.asOf)}</dd></div><div><dt>CDP match</dt><dd>${esc(src.cdpMatch??'No confirmed CDP match')}</dd></div>${src.cdpId?`<div><dt>CDP inventory ID / original SKU</dt><dd>${esc(src.cdpId)} / ${esc(src.cdpSku)}</dd></div><div><dt>CDP purchase price · unconfirmed</dt><dd>${esc(src.cdpPurchasePriceReported||'Blank')}<br><span class="field-help">Not applied as cost. May be a default or repeated lot total.</span></dd></div>`:''}<div><dt>Autograph described in source</dt><dd>${src.autographClaimed?'Yes · needs verification':'Not identified'}</dd></div>${src.cdpSerialReported?`<div><dt>CDP serial text · unverified</dt><dd>${esc(src.cdpSerialReported)}</dd></div>`:''}</dl>${src.reviewReason?`<div class="alert">${esc(src.reviewReason)}</div>`:''}${/^\d+$/.test(item.externalId)?`<a class="btn small" href="https://www.ebay.com/itm/${esc(item.externalId)}" target="_blank" rel="noopener noreferrer">Open source eBay listing ↗</a>`:''}${sales.length?`<h3>Imported sale evidence</h3><p class="field-help">These units are excluded from available stock. Fees, refunds, postage and COGS still need financial reconciliation; no net profit is assigned.</p>${sales.map(s=>`<div class="sale-row"><div><b>${esc(s.orderId)} · ${s.quantity} unit${s.quantity===1?'':'s'}</b><br>${esc(s.createdAt.slice(0,10))} · item amount ${money(s.revenueCents)}<br>${esc(s.paymentStatus)} · ${esc(s.fulfillmentStatus)}</div></div>`).join('')}`:''}</section>`;
}
function externalSalesPanel(){
  const sales=state.externalSales??[];if(!sales.length)return '';
  return `<section class="panel" style="margin-top:22px"><div class="panel-head" style="padding-bottom:16px"><h2>Imported eBay sales <span class="count">${sales.length} lines</span></h2><span class="muted" style="font-size:10px">Not included in recorded net profit</span></div><div class="table-wrap"><table><thead><tr><th>Item / order</th><th>Item amount</th><th>Payment status</th><th>Financials</th></tr></thead><tbody>${sales.map(s=>{const item=state.items.find(i=>i.id===s.itemId);return `<tr><td><button class="item-title" data-action="detail" data-id="${esc(item.id)}">${esc(item.title)}</button><div class="item-meta">${esc(s.orderId)} · ${s.quantity} units</div></td><td class="amount">${money(s.revenueCents)}</td><td>${esc(s.paymentStatus)}</td><td class="muted">Needs reconciliation</td></tr>`;}).join('')}</tbody></table></div><div class="table-foot">Item amounts are before refund/expense reconciliation. Shipping is not allocated here.</div></section>`;
}
function sourceSummary(){
  if(state.ebayRefresh?.source==='ebay-active-api'){const r=state.ebayRefresh;openModal('Daily eBay inventory update','CDP master SKUs preserved.',`<dl class="details">${[['Observed',new Date(r.observedAt).toLocaleString()],['Active eBay listings',r.stats.sourceRows],['Exact listing matches',r.stats.matched],['New records held for review',r.stats.added],['eBay price updates',r.stats.priceUpdates],['Manual price conflicts',r.stats.priceConflicts],['Quantity differences',r.stats.quantityConflicts],['Listings not observed',r.stats.missing],['Listings without SKU',r.stats.blankSku],['SKU mapping conflicts',r.stats.skuConflicts],['Blocked / variation review',r.stats.blocked]].map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><p>eBay is the current listing observation. CDP stays the master SKU source and listing hub. Physical quantities, existing review holds, costs, sales, identities and CollX prices are preserved. Missing listings are not confirmed sales.</p>${r.blocked.length?`<ul>${r.blocked.slice(0,50).map(x=>`<li>${esc(x.sku||x.id)} — ${esc(x.reason)}</li>`).join('')}</ul>`:''}<p class="field-help">New listings enter review with zero counted physical units until reconciled. Listing SKUs are aliases; they do not establish a CDP mapping. Live pagination can change during collection.</p>`);return;}

  const b=state.importBatches?.find(x=>x.id==='btco-inventory-20261011');
  openModal('Inventory import details','Sources preserved. No marketplace changes.',`${b?`<dl class="details">${[['eBay snapshot',`${b.stats.ebaySnapshotListings} listings / ${b.stats.ebaySnapshotUnits} units · October 6`],['CDP source',`${b.stats.cdpSnapshotRows} records · September 26`],['CDP details matched',b.stats.cdpEnriched],['Historical CDP records held for review',b.stats.cdpHistoricalReview],['Recent paid/non-cancelled orders',`${b.stats.externalOrders} orders / ${b.stats.externalUnitsSold} units`],['Cancelled/relisted identity review',b.stats['cancel/relist review']]].map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><div class="alert">${(b.limitations??[]).map(esc).join('<br><br>')}</div>`:'<p>Each imported item retains its report date and source row.</p>'}<p class="field-help">Browser records that already existed are preserved; matching IDs, listing IDs or SKUs are skipped during imports. Imported costs remain unknown until reviewed. Mac and iPhone share saved inventory when signed in with the same ChatGPT account.</p><div class="actions"><button class="btn" data-action="backup">Back up & import</button><button class="btn primary" data-action="ebay-csv">Import eBay active-listings CSV</button></div>`);
}
function ebayCSVDialog(){
  openModal('Refresh eBay inventory','Preview a source report. No marketplace writes.',`<div class="alert">For a separate reviewed report, upload an eBay Seller Hub active-listings CSV to refresh prices and add new records. Quantity differences are held for review. Costs, locations and recorded sales are preserved.</div><form id="ebay-csv-form"><div class="form-grid"><label>Report date *<input type="date" name="asOf" max="${localDate()}" required><span class="field-help">Use the export date. Same-day manual prices are protected.</span></label><label>eBay CSV *<input type="file" name="file" accept=".csv,text/csv" required></label><label class="check full"><input type="checkbox" name="complete">This report contains ALL active listings</label><p class="field-help full">Only select this for an unfiltered, complete report. Missing listings will be held for review; they will not be marked sold or deleted.</p></div><p id="form-error" class="error" role="alert"></p><div id="csv-preview"></div><div class="form-actions"><button class="btn primary" type="submit">Preview refresh</button></div></form>`);
  $('#ebay-csv-form').addEventListener('submit',async e=>{e.preventDefault();pendingRefresh=null;$('#form-error').textContent='';$('#csv-preview').innerHTML='';try{
    if(mode!=='work')throw Error('Open working inventory before importing real records.');
    const f=new FormData(e.target),file=f.get('file');if(file.size>15000000)throw Error('Maximum report size is 15 MB.');
    const text=await file.text(),incoming=ebayCSVState(text,{asOf:String(f.get('asOf')),fileName:file.name}),plan=previewEbayRefresh(state,incoming,{complete:f.has('complete'),checksum:await hashText(text)});
    pendingRefresh={plan,revision:state.revision};
    const p=plan.stats;
    $('#csv-preview').innerHTML=`<div class="import-result"><strong>${p.added} new records · ${p.priceUpdates} price updates</strong><br>${p.matched} exact listing-ID matches<br>${p.quantityConflicts} quantity conflicts · ${p.missing} missing from complete report<br>${p.priceConflicts} newer/manual prices protected · ${p.blocked} identity/date conflicts skipped</div><p class="field-help">${p.quantityConflicts+p.missing} records will be excluded from available stock until reviewed.</p><ul class="import-list">${[...plan.blocked,...plan.matched.filter(m=>m.quantityConflict||m.priceConflict).map(m=>({sku:m.row.sku,title:m.row.title,reason:m.quantityConflict?`Quantity: Vault ${m.available}, report ${m.row.quantity}`:'A newer/manual Vault price is preserved'})),...plan.missing.map(m=>({...m,reason:'Missing from complete report'}))].slice(0,30).map(m=>`<li>${esc(m.sku)} — ${esc(m.reason)}</li>`).join('')}</ul><button class="btn primary" type="button" data-action="apply-refresh">Apply reviewed refresh</button>`;
  }catch(error){modalError(error);}});
}
function field(name,label,value='',props=''){return `<label>${label}<input name="${name}" value="${esc(value)}" ${props}></label>`;}
function dollars(c){return c==null?'':(c/100).toFixed(2);}
function itemForm(id){const item=id?state.items.find(i=>i.id===id):makeItem({sku:`BT-${localDate().replaceAll('-','')}-${uid().slice(0,4).toUpperCase()}`,acquiredDate:localDate()}),locked=state.sales.some(s=>s.itemId===id&&!s.voidedAt)||(item.sourceSoldQuantity??0)>0,select=(name,label,values)=>`<label>${label}<select name="${name}">${options(values,item[name])}</select></label>`;
  openModal(id?'Edit inventory':'Receive inventory',mode==='demo'?'Demo workspace · Changes stay separate from your actual inventory.':'One SKU represents a single item, identical units, or one intact lot.',`<form id="item-form"><div class="form-grid"><div class="form-section">Identity</div><label class="full">Item title *<input name="title" required maxlength="240" value="${esc(item.title)}" placeholder="e.g. 2019 Gypsy Queen Max Muncy autograph"></label>${field('sku','Inventory / marketplace SKU *',item.sku,'required maxlength="80"')}${cdpSku(item)?`<p class="field-help full">CDP master SKU: <strong>${esc(cdpSku(item))}</strong>. Manage listings in CDP; this form edits the Vault record.</p>`:'<p class="field-help full">For CDP-managed cards, use the exact CDP SKU. Vision intake can save a draft until that SKU is available.</p>'}${select('kind','Collectible type',TYPES)}${field('subject','Player / character / series',item.subject)}${field('year','Year / era',item.year,'maxlength="30"')}${field('setName','Set / publisher',item.setName)}${field('number','Card number / issue',item.number)}${field('parallel','Parallel / variant',item.parallel)}${field('serial','Stamped serial',item.serial,'placeholder="e.g. 001/199; verify front/back"')}<label class="check full"><input name="autograph" type="checkbox" ${item.autograph?'checked':''}>Genuine autograph identified</label>${field('gradeCompany','Grading company',item.gradeCompany,'placeholder="PSA, SGC, CGC…"')}${field('grade','Grade',item.grade)}<label class="full">Certification number<input name="cert" value="${esc(item.cert)}" placeholder="Record only; not automatically verified"></label><div class="form-section">Physical inventory</div>${field('quantity','Sellable units *',item.quantity,`type="number" min="${item.availability==='review'?0:1}" max="1000000" step="1" required ${locked?'disabled':''}`)}${select('verification','Physical verification',VERIFY)}<label class="full">Storage location<input name="location" value="${esc(item.location)}" list="locations" placeholder="Office / Box A / Row 1"><datalist id="locations">${[...new Set(state.items.map(i=>i.location).filter(Boolean))].map(l=>`<option value="${esc(l)}">`).join('')}</datalist><span class="field-help">An intact 100-card lot is 1 sellable unit. Put its contents in notes.</span></label>${item.source?`<label class="full">Inventory counting<select name="availability">${options(['tracked','review'],item.availability??'tracked',{tracked:'Count available units',review:'Hold for reconciliation'})}</select><span class="field-help">Historical records require physical verification before counting. Source quantities are a dated reference, not a current census.</span></label>`:''}<div class="form-section">Acquisition & cost</div>${field('vendor','Seller / source',item.vendor)}${field('acquisitionRef','Purchase / lot reference',item.acquisitionRef,'placeholder="e.g. Dave — September lot"')}${field('acquiredDate','Acquired date',item.acquiredDate,'type="date"')}<label>Allocated cost for ALL these units ($)<input name="costCents" inputmode="decimal" value="${dollars(item.costCents)}" placeholder="Blank = unknown" ${locked?'disabled':''}><span class="field-help">Include allocated purchase price, inbound shipping and tax. Enter 0 for free. Do not repeat the full purchase-lot cost on every item.</span></label>${locked?'<p class="field-help full">Quantity and cost are locked to preserve recorded sale cost snapshots.</p>':''}<div class="form-section">Listing workflow · manual only</div>${select('status','Workflow status',STATUSES)}${!['ebay','collx'].includes(item.channel.trim().toLowerCase())?field('askCents','Target asking price ($)',dollars(item.askCents),'inputmode="decimal" placeholder="Optional"'):''}${field('channel','Listing channel',item.channel,'placeholder="eBay, CollX, Whatnot, local…"')}${field('externalId','External listing ID',item.externalId)}<div class="form-section">Channel listing prices · USD per sellable unit</div>${field('ebayPrice','eBay listing price ($)',dollars(listingPrice(item,'ebay').priceCents),'inputmode="decimal" placeholder="Not captured"')}${field('collxPrice','CollX listing price ($)',dollars(listingPrice(item,'collx').priceCents),'inputmode="decimal" placeholder="Not captured"')}<p class="field-help full">Record the actual asking price for each channel separately. Blank means not captured. Prices may differ. Saving records prices in Vault; the source listings are unchanged.</p><label class="full">Notes / condition / lot contents<textarea name="notes" maxlength="4000">${esc(item.notes)}</textarea></label></div><p class="error" id="form-error" role="alert"></p><div class="form-actions"><button type="button" class="btn" data-action="close">Cancel</button><button class="btn primary" type="submit">${id?'Save changes':'Add to Vault'}</button></div></form>`);
  $('#item-form').addEventListener('submit',async e=>{e.preventDefault();try{const f=new FormData(e.target),next={...item};for(const [k,v] of f)if(!['autograph','ebayPrice','collxPrice'].includes(k))next[k]=String(v).trim();next.autograph=f.has('autograph');next.quantity=locked?item.quantity:Number(f.get('quantity'));next.costCents=locked?item.costCents:cents(f.get('costCents'),true);next.askCents=f.has('askCents')?cents(f.get('askCents'),true):item.askCents;next.listingPrices=updateListingPrices(item,{ebay:cents(f.get('ebayPrice'),true),collx:cents(f.get('collxPrice'),true)},localDate());await persist(saveItem(state,next));closeModal();toast(id?'Inventory updated.':'Item added to Vault.');}catch(err){modalError(err);}});
}
function intakeEvidence(item){const records=intakeRecords(state).filter(r=>r.linkedItemId===item.id);return records.length?`<section class="source-detail"><h3>Linked Vision intake</h3><p class="field-help">These reviewed drafts are attached to this CDP record. Existing inventory fields and quantities were preserved when linking.</p>${records.map(r=>`<details><summary>${esc(r.title)} · ${esc(new Date(r.linkedAt).toLocaleString())}</summary><p>CDP SKU ${esc(r.cdpSku)} · Draft cost ${money(r.costCents)} · ${esc(r.location||'Location not recorded')}</p><pre class="vision-json-result">${esc(JSON.stringify(r.card,null,2))}</pre></details>`).join('')}</section>`:'';}
function publicPSARecord(item){const links=item.gradeCompany.trim().toUpperCase()==='PSA'?psaPublicLinks(item.cert):null;return links?`<section class="source-detail"><h3>PSA certificate ${esc(links.cert)}</h3><div class="actions"><a class="btn" href="${esc(links.google)}" target="_blank" rel="noopener noreferrer">Google this cert ↗</a><a class="btn" href="${esc(links.official)}" target="_blank" rel="noopener noreferrer">Open PSA record ↗</a></div><p class="field-help">Compare the official record with the physical slab. Opening a link does not mark the item verified.</p></section>`:'';}
function detail(id){const i=state.items.find(x=>x.id===id);if(!i)return;const sales=state.sales.filter(s=>s.itemId===id),pairs=[['Inventory / marketplace SKU',i.sku],['CDP master SKU',cdpSku(i)||'Not linked'],['CDP link basis',i.cdpLink?'Manually checked in CDP · '+i.cdpLink.confirmedAt:i.source?.cdpSku?'Imported CDP source · '+(i.source.asOf||'date not recorded'):'Not linked'],['Type',labels[i.kind]],['Available / reference quantity',i.availability==='review'?`Unreconciled · ${i.quantity} in the source`:`${remaining(state,i)} / ${i.quantity} sellable units`],['Physical check',labels[i.verification]],['Location',i.location||'Unassigned'],['Allocated acquisition cost',money(i.costCents)],['Remaining cost',money(remainingCost(state,i))],...(!['ebay','collx'].includes(i.channel.trim().toLowerCase())?[['Target asking price',money(i.askCents)]]:[]),['Player / series',i.subject||'—'],['Year / set / number',[i.year,i.setName,i.number].filter(Boolean).join(' · ')||'—'],['Parallel / serial',[i.parallel,i.serial].filter(Boolean).join(' · ')||'—'],['Autograph',i.autograph?'Yes, manually identified':'Not recorded'],['Grading',[i.gradeCompany,i.grade,i.cert].filter(Boolean).join(' · ')||'Raw / not recorded'],['Purchase',[i.vendor,i.acquisitionRef,i.acquiredDate].filter(Boolean).join(' · ')||'Not recorded'],['Listing record',[i.channel,i.externalId].filter(Boolean).join(' · ')||'Not recorded']];
  openModal('Inventory record',mode==='demo'?'Fictional sample inventory':'Shared inventory · source dates are preserved',`${badge(status(state,i))} <h3 class="detail-title">${esc(i.title)}</h3><div class="detail-actions"><button class="btn" data-action="edit" data-id="${id}">${icon('edit',14)}Edit item</button><button class="btn primary" data-action="sell" data-id="${id}" ${remaining(state,i)===0||i.verification==='awaiting'?'disabled':''}>Record sale</button></div>${i.verification==='awaiting'?'<p class="field-help">Receive this item before recording a sale.</p>':''}<dl class="details">${pairs.map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>${i.notes?`<div class="detail-note">${esc(i.notes)}</div>`:''}${intakeEvidence(i)}${publicPSARecord(i)}${channelDetails(i)}${ebaySnapshotDetails(i)}${sourceDetails(i)}<div class="detail-sales"><h3>Sales & cost history</h3>${sales.length?sales.map(s=>`<div class="sale-row ${s.voidedAt?'voided':''}"><div><strong>${esc(s.date)} · ${s.quantity} unit${s.quantity===1?'':'s'} · ${esc(s.channel)||'Direct'}</strong><br>Proceeds ${money(s.revenueCents)} + shipping ${money(s.shippingCollectedCents)}<br>COGS ${money(s.cogsCents)} · selling fees ${money(s.sellingFeeCents)} · promotion ${money(s.promoFeeCents)}<br>Postage ${money(s.postageCents)} · supplies ${money(s.suppliesCents)} · refunds ${money(s.refundCents)}<br><b>Net: ${money(profit(s))}${s.voidedAt?' · VOIDED':''}</b>${s.reference?`<br>Reference: ${esc(s.reference)}`:''}</div>${!s.voidedAt?`<button class="btn small" data-action="void-prompt" data-id="${s.id}">Void</button>`:''}</div>`).join(''):'<p class="muted">No sales recorded.</p>'}</div>`);
}
function saleForm(id){const item=state.items.find(i=>i.id===id);if(!item)return;const moneyInput=(name,label,value='')=>field(name,label,value,'inputmode="decimal" placeholder="0.00" required');
  openModal('Record a sale',item.title,`<div class="alert">Enter actual amounts for the entire quantity sold. Exclude marketplace-collected sales tax from proceeds; include all fees actually charged. Blank is not zero. This records a sale in Vault.</div><form id="sale-form"><div class="form-grid">${field('quantity','Units sold',1,`type="number" min="1" max="${remaining(state,item)}" step="1" required`)}${field('date','Sale date',localDate(),'type="date" required')}${field('channel','Sales channel',item.channel,'placeholder="eBay / CollX / local"')}${field('reference','Order reference','')}${moneyInput('revenueCents','Item proceeds ($)')}${moneyInput('shippingCollectedCents','Shipping collected ($)','0.00')}<div class="form-section">Actual expenses · enter 0 when none</div>${moneyInput('sellingFeeCents','Marketplace / payment fees ($)')}${moneyInput('promoFeeCents','Promotional fees ($)')}${moneyInput('postageCents','Outbound postage ($)')}${moneyInput('suppliesCents','Shipping supplies ($)')}${moneyInput('refundCents','Refunds / adjustments paid ($)','0.00')}<label>Cost basis<span class="field-help">${item.costCents==null?'Unknown. Profit will remain unknown.':`${money(remainingCost(state,item))} across ${remaining(state,item)} remaining units. Automatically allocated to this sale.`}</span></label><label class="full">Notes<textarea name="notes"></textarea></label></div><div class="sale-estimate" id="sale-estimate">Fill in the actual amounts to calculate net profit.</div><p class="field-help">For sourcing estimates, BTCo budgets at least 5% promotion. Recorded sales use the actual promotional fee.</p><p id="form-error" class="error" role="alert"></p><div class="form-actions"><button class="btn" type="button" data-action="detail" data-id="${id}">Cancel</button><button class="btn primary" type="submit">Save sale</button></div></form>`);
  const read=()=>{const f=new FormData($('#sale-form'));return {itemId:id,quantity:Number(f.get('quantity')),date:f.get('date'),channel:String(f.get('channel')).trim(),reference:String(f.get('reference')).trim(),notes:String(f.get('notes')).trim(),...Object.fromEntries(['revenueCents','shippingCollectedCents','sellingFeeCents','promoFeeCents','postageCents','suppliesCents','refundCents'].map(k=>[k,cents(f.get(k))]))};};
  $('#sale-form').addEventListener('input',()=>{try{const preview=recordSale(state,read()),sale=preview.sales.at(-1),p=profit(sale);$('#sale-estimate').innerHTML=`Net profit after all recorded costs <b class="${p<0?'negative':'positive'}">${money(p)}</b>`;}catch{$('#sale-estimate').textContent='Fill in every amount (0 when none) to calculate net profit.';}});
  $('#sale-form').addEventListener('submit',async e=>{e.preventDefault();try{await persist(recordSale(state,read()));detail(id);toast('Sale recorded. Stock and profit updated.');}catch(err){modalError(err);}});
}
function backup(){openModal('Back up & import',`${mode==='demo'?'Demo':'Working'} workspace · Schema v${VERSION}`,`<div class="alert">Working inventory syncs through your ChatGPT account. Each shared save retains a recovery snapshot (latest 10). JSON import adds new SKUs only; it does not overwrite existing records. Demo inventory stays local.</div><div class="backup-option"><h3>Recovery snapshots</h3><p>Download a previous shared version, a preserved device copy or your latest local save draft.</p><button class="btn" data-action="cloud-backups">View recovery snapshots</button></div><div class="backup-option"><h3>Full JSON backup</h3><p>Download items, sales, price observations and change history. Keep an independent copy of your shared inventory.</p><button class="btn primary" data-action="export-json">${icon('download',14)}Export ${mode==='demo'?'demo':'working'} backup</button></div><div class="backup-option"><h3>Spreadsheet-friendly exports</h3><p>Download inventory or the sales ledger as CSV. Use the active-listings CSV importer below for a new eBay snapshot.</p><div class="actions"><button class="btn" data-action="export-csv">Inventory CSV</button><button class="btn" data-action="export-sales">Sales CSV</button></div></div><div class="backup-option"><h3>Refresh from an eBay active-listings report</h3><p>Preview price changes, new listings and stock discrepancies. No live marketplace changes.</p><button class="btn" data-action="ebay-csv">Preview an eBay CSV</button></div><div class="backup-option"><h3>Import a BTCo OS JSON backup</h3><p>Preview before adding. Duplicate IDs or SKUs and their sales are skipped. Demo and working backups cannot mix.</p><input type="file" id="import-file" accept=".json,application/json" aria-label="Choose a BTCo OS backup"><div id="import-preview"></div></div><p class="error" id="form-error" role="alert"></p>`);
  $('#import-file').addEventListener('change',async e=>{const f=e.target.files[0];pendingImport=null;$('#form-error').textContent='';$('#import-preview').innerHTML='';if(!f)return;try{if(f.size>15_000_000)throw Error('Maximum backup size is 15 MB for this prototype.');const incoming=JSON.parse(await f.text()),p=previewImport(state,incoming);pendingImport=incoming;$('#import-preview').innerHTML=`<div class="import-result"><strong>${p.accepted.length} new SKUs · ${p.sales.length} sale records · ${p.acceptedIntakes.length} intake drafts</strong><br>${p.skipped.length} existing SKUs skipped without changes.</div><ul class="import-list">${p.accepted.slice(0,30).map(i=>`<li>${esc(i.sku)} — ${esc(i.title)}</li>`).join('')}</ul><button class="btn primary" data-action="apply-import" ${p.accepted.length||p.acceptedIntakes.length?'':'disabled'}>Import new records</button>`;}catch(err){modalError(err);}});
}
function pulse(){const live=state.sales.filter(s=>!s.voidedAt).slice().reverse();return `<section class="panel"><div class="panel-head"><h2>Recorded sales</h2><button class="text-btn" data-action="export-sales">Export ledger</button></div>${live.length?`<div class="table-wrap"><table><thead><tr><th>Item / sale date</th><th>Proceeds¹</th><th>Cost basis</th><th>Fees²</th><th>Net profit</th></tr></thead><tbody>${live.map(s=>{const i=state.items.find(x=>x.id===s.itemId);return `<tr><td><button class="item-title" data-action="detail" data-id="${i.id}">${esc(i.title)}</button><div class="item-meta">${esc(s.date)} · ${s.quantity} units · ${esc(s.channel)||'Direct'}</div></td><td class="amount">${money(s.revenueCents+s.shippingCollectedCents)}</td><td>${money(s.cogsCents)}</td><td>${money(s.sellingFeeCents+s.promoFeeCents+s.postageCents+s.suppliesCents+s.refundCents)}</td><td class="amount ${profit(s)<0?'negative':'positive'}">${money(profit(s))}</td></tr>`;}).join('')}</tbody></table></div><div class="table-foot">¹ Item proceeds + shipping collected. ² Fees, promotion, postage, supplies and refunds.</div>`:'<div class="empty"><h3>No financially reconciled sales yet.</h3><p>Imported eBay sales appear below. Record complete costs and fees before claiming net profit.</p><button class="btn primary" data-nav="vault">Open Vault</button></div>'}</section>${externalSalesPanel()}<section class="panel" style="margin-top:22px"><div class="panel-head" style="padding-bottom:16px"><h2>Recent activity</h2><span class="muted" style="font-size:10px">Change history · not a tamper-proof audit</span></div>${state.events.slice(-12).reverse().map(e=>`<div class="activity"><strong>${esc(e.action.replaceAll('.',' · '))}</strong><span>${esc(new Date(e.at).toLocaleString())}</span></div>`).join('')||'<div class="activity">No changes yet.</div>'}</section>`;}
const modules=[['vision','Vision','Capture and identify','Review scan results, find shared Vault candidates, receive a physical copy and estimate buying costs. Hosted recognition and PSA connect through protected provider credentials.','Hosted workflow'],['vault','Vault','Inventory is the foundation','Physical stock, unique SKUs, allocated costs, locations and identification. The source of truth for every item.','Working MVP'],['scout','Scout','Find the next opportunity','Exact-card comps, delivered buy cost, liquidity and buying limits. Minimum 5% promotion in sourcing estimates.','Planned'],['market','Market','Get the right item listed','Channel listings, prices and reconciliation. Connect eBay read-only first; add explicit write workflows later.','Manual fields'],['flow','Flow','Keep the work moving','Receiving, verification, picking and shipping. Today: receive items and record or void recorded sales.','Basic workflow'],['pulse','Pulse','See what the work earns','Stock cost, outstanding costs and recorded profit. Future: inventory age, sell-through and capital turnover.','Basic summary']];
function foundation(){return `<section class="module-grid">${modules.map(([id,name,title,copy,stage])=>`<article class="module-card">${icon(id,25)}<h3>${name} <span class="muted" style="font-weight:400;font-size:12px">/ ${title}</span></h3><p>${copy}</p><span class="badge ${stage==='Planned'?'hold':'verified'}">${stage}</span></article>`).join('')}</section><section class="panel architecture"><div class="eyebrow">Architecture / v0.6</div><h2>A modular monolith, with Vault at the center.</h2><p>Today: a responsive client, shared domain rules, a signed-in API and hosted inventory storage. Original browser records are preserved, with automatic recovery snapshots and conflict checks. Next: a typed API, PostgreSQL, private object storage and an outbox worker. All business records belong to a dealer.</p><div class="table-wrap"><table><thead><tr><th>Data boundary</th><th>Production entities</th></tr></thead><tbody><tr><td>Ownership</td><td>dealers · memberships · scoped integration accounts</td></tr><tr><td>Acquisitions</td><td>acquisitions · items · cost_allocations</td></tr><tr><td>Physical stock</td><td>locations · stock_movements · collectible_details</td></tr><tr><td>Sales channels</td><td>listings · sales · sale_lines · sale_expenses</td></tr><tr><td>Trust & evidence</td><td>assets · import_batches · audit_events · integration_jobs</td></tr></tbody></table></div><h3>What works today</h3><p>Add and edit inventory. View and record separate eBay and CollX listing prices. Open eBay records without CDP matches from the homepage count. Track cards, comics, graded items and intact lots. Separate physical verification from listing status. Record partial sales with cost allocation and actual fees. Void mistaken sales while keeping history. Search and filter. Export inventory, sales or a full backup. Preview imports and append new SKUs without overwriting existing data.</p><h3>What comes next</h3><ol><li><strong>Reconcile real inventory:</strong> preserve source exports; map SKUs, review duplicate identities, distinguish sold items and physically verified reserves, and stage imports for approval.</li><li><strong>Shared persistence:</strong> now available for the same signed-in account. Team memberships and commercial dealer onboarding remain future work.</li><li><strong>Acquisition controls:</strong> allocate a purchase lot across items, split bulk lots with cost conservation, and reconcile unknown sale costs.</li><li><strong>Integrations:</strong> eBay read-only matching and order/fee imports, then scanning and explicitly authorized listing updates.</li></ol><p><strong>Prototype limits:</strong> an internet connection is required to save shared inventory. Vision supports manual identity review and an optional recognition service. Photo retention and native shared-account sync remain future work. Source export import and reconciliation are available; no saved photos, automated sold valuations, multi-channel stock reservation, marketplace writes or purchases. Bulk lots are intact sellable units; itemized lot splitting is not implemented. Net profit excludes business overhead and income taxes.</p><div class="arch-actions"><a class="btn" href="./architecture.md" download>Download architecture & plan</a><a class="btn" href="./schema.sql" download>Download proposed SQL schema</a></div></section>`;}
document.addEventListener('click',async e=>{const nav=e.target.closest('[data-nav]');if(nav){const n=nav.dataset.nav;if(['vault','vision','scout','market','flow','pulse','foundation'].includes(n)){view=n;render();window.scrollTo(0,0);}return;}
  const tab=e.target.closest('[data-type]');if(tab){type=tab.dataset.type;page=1;render();return;}
  const channelButton=e.target.closest('[data-coverage]');if(channelButton){coverage=channelButton.dataset.coverage;type=filter=verification='all';search='';page=1;render();$('#inventory-results').scrollIntoView({block:'start'});return;}
  const queue=e.target.closest('[data-queue]');if(queue){coverage='all';type='all';search='';filter=queue.dataset.queue==='unverified'?'all':queue.dataset.queue;verification=queue.dataset.queue==='unverified'?'unverified':'all';page=1;render();return;}
  const btn=e.target.closest('[data-action]');if(btn){const a=btn.dataset.action,id=btn.dataset.id;try{
    if(a==='close')closeModal();if(a==='switch-mode')await changeMode();if(a==='add')itemForm();if(a==='edit')itemForm(id);if(a==='detail')detail(id);if(a==='sell')saleForm(id);if(a==='backup')backup();if(a==='source-summary')sourceSummary();if(a==='refresh-shared')await refreshSharedNow();if(a==='cloud-backups')await cloudBackups();if(a==='device-review')migrationReview();if(a==='dismiss-migration'){await dismissMigration();closeModal();render();}if(a==='download-draft'){const draft=await localDraft();if(!draft)throw Error('No saved draft on this device.');download('BTCo-OS-unsynced-draft.json',JSON.stringify(draft,null,2));}if(a==='download-snapshot'){const result=await sharedRequest('/history?revision='+encodeURIComponent(id));download('BTCo-OS-revision-'+id+'.json',JSON.stringify(result.state,null,2));}if(a==='download-device'){const result=await sharedRequest('/history?backup='+encodeURIComponent(id));download('BTCo-OS-device-backup.json',JSON.stringify(result.state,null,2));}if(a==='apply-refresh'&&pendingRefresh){if(pendingRefresh.revision!==state.revision)throw Error('Inventory changed. Preview the report again.');const plan=pendingRefresh.plan;await persist(applyEbayRefresh(state,plan));closeModal();toast('eBay report applied. Discrepancies are held for review.');}if(a==='ebay-csv')ebayCSVDialog();
    if(a==='export-json')download(`BTCo-OS-${mode}-${localDate()}.json`,JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2));
    if(a==='export-csv')download(`BTCo-OS-${mode}-inventory-${localDate()}.csv`,'\ufeff'+inventoryCSV(state),'text/csv;charset=utf-8');
    if(a==='export-sales')download(`BTCo-OS-${mode}-sales-${localDate()}.csv`,'\ufeff'+salesCSV(state),'text/csv;charset=utf-8');
    if(a==='clear-filters'){type='all';filter=verification=coverage='all';search='';page=1;render();}
    if(a==='previous'){page=Math.max(1,page-1);renderResults();}if(a==='next'){page++;renderResults();}
    if(a==='apply-import'&&pendingImport){const preview=previewImport(state,pendingImport),count=preview.accepted.length,drafts=preview.acceptedIntakes.length;await persist(mergeImport(state,pendingImport));closeModal();toast(`${count} new SKUs and ${drafts} intake drafts imported. Existing records preserved.`);}
    if(a==='void-prompt'){const s=state.sales.find(x=>x.id===id);openModal('Void an incorrect sale?','A correction to this local record only.',`<p style="font-size:13px;line-height:1.8">This preserves the original sale, removes it from recorded profit, and restores ${s.quantity} unit${s.quantity===1?'':'s'} to available inventory. It does not issue a refund or change any marketplace.</p><div class="form-actions"><button class="btn" data-action="detail" data-id="${s.itemId}">Cancel</button><button class="btn danger" data-action="void" data-id="${id}">Void sale</button></div>`);}
    if(a==='void'){const itemId=state.sales.find(s=>s.id===id).itemId;await persist(voidSale(state,id));detail(itemId);toast('Sale voided. Original record preserved.');}
  }catch(err){modalError(err);}return;}
  const row=e.target.closest('[data-item]');if(row)detail(row.dataset.item);
});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
window.addEventListener('storage',e=>{if(e.key===key(mode))toast('Inventory changed in another tab. Reload before editing.');});

function syncPanel(){
  if(mode==='demo')return '';
  const connected=syncStatus.phase==='connected',r=state.ebayRefresh;
  return `<section class="sync-panel ${connected?'':'sync-offline'}" aria-label="Shared inventory status"><div><strong>${connected?'Shared across your devices':'Offline copy · read only'}</strong><p>${connected?`Saved revision ${state.revision}${syncStatus.updatedAt?' · '+esc(new Date(syncStatus.updatedAt).toLocaleString()):''}`:esc(syncStatus.message||'Reconnect to save changes.')}</p>${syncStatus.conflicts.length?`<button class="text-btn" data-action="device-review">Review ${syncStatus.conflicts.length} preserved device differences</button>`:''}<p>eBay ${r?`report: ${esc(r.asOf)} · applied ${esc(new Date(r.importedAt).toLocaleString())}`:'no API observation saved'}${r?.source==='ebay-active-api'?' · API refresh verified. CDP master SKUs preserved.':' · No API refresh saved yet.'}</p></div><div class="actions"><button class="btn small" data-action="refresh-shared">${connected?'Reload shared inventory':'Reconnect'}</button><button class="btn small" data-action="ebay-csv">Refresh eBay report</button><button class="btn small" data-action="cloud-backups">Recovery snapshots</button></div></section>`;
}
async function refreshSharedNow(){
  if(refreshBusy)return;if($('#modal').open){toast('Close the open dialog before reloading shared inventory. Your draft is kept.');return;}
  refreshBusy=true;
  try{state=syncStatus.phase==='connected'?await readWorkspace('work'):await connectShared(await readLocalWorkspace('work'));page=1;render();toast('Shared inventory is up to date.');}
  catch(error){syncStatus.phase='offline';syncStatus.message=error.message;render();toast(error.message);}
  finally{refreshBusy=false;}
}
async function cloudBackups(){
  if(mode==='demo'){toast('Recovery snapshots are for working inventory. Demo records stay in this browser.');return;}
  openModal('Recovery snapshots','Shared history and preserved device copies',`<p class="field-help">Loading saved versions…</p>`);
  const data=await sharedRequest('/history');
  openModal('Recovery snapshots','The latest 10 shared saves are retained automatically.',`<p class="field-help">Download a previous version before making a correction. Downloading a snapshot does not replace current inventory. Original device copies remain available separately.</p><h3 class="small-heading">Shared saves</h3>${data.history.map(h=>`<div class="recovery-row"><span><b>Revision ${h.revision}</b><br>${esc(new Date(h.created_at).toLocaleString())}</span><button class="btn small" data-action="download-snapshot" data-id="${h.revision}">Download JSON</button></div>`).join('')||'<p>No shared saves yet.</p>'}<h3 class="small-heading">Preserved device inventory</h3>${data.devices.map(d=>`<div class="recovery-row"><span><b>${esc(d.label)}</b><br>${esc(new Date(d.created_at).toLocaleString())}</span><button class="btn small" data-action="download-device" data-id="${esc(d.id)}">Download JSON</button></div>`).join('')||'<p class="field-help">No device differences needed a separate backup.</p>'}<div class="backup-option"><h3>Latest local save draft</h3><p>A copy is kept before each shared save, including saves rejected because another device changed inventory.</p><button class="btn" data-action="download-draft">Download this device’s draft</button></div><p class="error" id="form-error" role="alert"></p>`);
}
function migrationReview(){
  const fields=[['location','Location'],['quantity','Reference quantity'],['costCents','Acquisition cost (cents)'],['notes','Notes'],['status','Workflow']];
  openModal('Preserved device differences','Shared records were kept. Your device copy is backed up.',`<p class="field-help">These records differ from both the original source and the shared inventory. Review the saved copy before editing the current record. Local sales need financial reconciliation; they were not silently merged.</p>${syncStatus.conflicts.slice(0,40).map(c=>c.kind==='intake'?`<div class="backup-option"><h3>Intake draft · ${esc(c.title)}</h3><p>Shared draft retained; the differing device draft remains in your backup.</p></div>`:`<div class="backup-option"><h3>${esc(c.sku)} · ${esc(c.title)}</h3><div class="comparison"><div><b>Device copy</b>${fields.map(([key,label])=>`<p>${label}: ${esc(c.local[key])}</p>`).join('')}<p>eBay: ${money(listingPrice(c.local,'ebay').priceCents)} · CollX: ${money(listingPrice(c.local,'collx').priceCents)}</p><p>${c.localSales} local sale differences</p></div><div><b>Shared record</b>${c.shared?fields.map(([key,label])=>`<p>${label}: ${esc(c.shared[key])}</p>`).join(''):'No matching record ID. Review SKU identity.'}</div></div>${c.shared?`<button class="btn small" data-action="detail" data-id="${esc(c.shared.id)}">Open shared record</button>`:''}</div>`).join('')}${syncStatus.conflicts.length>40?'<p>First 40 shown. The complete device copy is available below.</p>':''}<div class="actions">${syncStatus.backupId?`<button class="btn" data-action="download-device" data-id="${esc(syncStatus.backupId)}">Download original device copy</button>`:''}<button class="btn" data-action="dismiss-migration">Acknowledge · keep shared records</button></div><p class="field-help">Acknowledging removes this reminder. The preserved backup remains available.</p>`);
}
function ebaySnapshotDetails(item){
  const s=item.ebaySnapshot;if(!s)return '';
  return `<section class="source-detail"><h3>Latest eBay report · ${esc(s.asOf)}</h3><dl class="details"><div><dt>Listing observation</dt><dd>${s.status==='active'?'Observed active':'Not observed in latest collection'}</dd></div>${s.listingSku!==undefined?`<div><dt>eBay listing SKU</dt><dd>${esc(s.listingSku||'Not supplied')}${s.skuConflict?' · review mapping':''}</dd></div>`:''}${s.reportedAvailable!==undefined?`<div><dt>Reported quantity</dt><dd>${esc(s.reportedAvailable)}${s.quantityConflict?' · requires reconciliation':''}</dd></div><div><dt>Reported eBay price</dt><dd>${money(s.reportedPriceCents)}${s.priceConflict?' · newer/manual Vault price preserved':''}</dd></div>`:''}</dl>${s.reviewReason?`<div class="alert">${esc(s.reviewReason)}</div>`:''}</section>`;
}
async function checkSharedUpdates(){
  if(mode!=='work'||refreshBusy||document.hidden||syncStatus.phase!=='connected')return;
  try{if(await sharedHasChanges()){if($('#modal').open)toast('Another device saved changes. Finish or close this dialog, then reload shared inventory.');else await refreshSharedNow();}}
  catch(error){syncStatus.message='Could not check other devices. '+error.message;}
}
window.addEventListener('focus',checkSharedUpdates);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkSharedUpdates();});
setInterval(checkSharedUpdates,60000);
